"""Fixed public role icons and reviewed bundled badge bases; no import-time I/O.

Sources are obfuscated game CDN paths or six exact official weapon URLs.
POWER is reported combat data plus typography, never a numeric image API.
"""
from __future__ import annotations

import base64
from dataclasses import dataclass
import hashlib
import json

from ..nikke_api.resource import obfuscate_path

WEAPON_NAMES = {
    'AR': 'assault_rifle', 'MG': 'machine_gun', 'SG': 'shot_gun',
    'RL': 'rocket_launcher', 'SMG': 'sub_machine_gun', 'SR': 'sniper_rifle',
}
WEAPON_URLS = {key: 'https://www.blablalink.com/assets/nikke/version/default/'
               f'shiftysassets/images/icon-weapon-{name}.png'
               for key, name in WEAPON_NAMES.items()}
FIXED_WEAPON_URLS = frozenset(WEAPON_URLS.values())
ELEMENT_KEYS = frozenset('icn_element_' + name for name in ('fire', 'water', 'wind', 'elect', 'iron'))


@dataclass(frozen=True)
class BaseIcon:
    kind: str
    key: str
    directory: str
    source: str

    @property
    def url(self):
        return self.source if self.kind == 'weapons' else obfuscate_path(self.source)


BASE_ICONS = tuple(
    [BaseIcon('attributes', key, 'rolemeta/icons', f'/icon/atlas_common_class/{key}.png')
     for key in sorted(ELEMENT_KEYS)]
    + [BaseIcon('attributes', f'icn_class_{key}', 'rolemeta/icons',
                f'/icon/atlas_common_class/icn_class_{key}.png')
       for key in ('attacker', 'defender', 'supporter')]
    + [BaseIcon('attributes', f'icn_burst_{key}', 'rolemeta/icons',
                f'/icon/atlas_common_class/icn_burst_{key}.png')
       for key in ('01', '02', '03', 'all')]
    + [BaseIcon('corporations', f'icn_corp_{number:02}', 'corporations',
                f'/icon/atlas_common_corp/icn_corp_{number:02}.png') for number in range(1, 6)]
    + [BaseIcon('weapons', key, 'rolemeta/weapons', url) for key, url in WEAPON_URLS.items()]
)
BASE_ICON_MAP = {(spec.kind, spec.key): spec for spec in BASE_ICONS}

# Audited official static PNGs, with no digits. See .references/community/base-icons.
# The official nikke-stars component overlays the reported core/grade separately.
STATIC_BADGES = {'star_inactive': {'url': 'https://www.blablalink.com/assets/nikke/version/default/assets/icon-nikke-star-Bv0b_V3C.png', 'sha256': 'cff1d74719ebf619e148a66b401ef2df536b485b9df9c04d84b93fece6a56c4e', 'base64': ''}, 'star_active': {'url': 'https://www.blablalink.com/assets/nikke/version/default/assets/icon-nikke-star-gold-BnTupWrm.png', 'sha256': '6ad388a8fdfcf7c9573b199ca210483f2dfe133ee0c835b23562df7cddfeab04', 'base64': ''}, 'core': {'url': 'https://www.blablalink.com/assets/nikke/version/default/shiftysassets/images/icon-evolve.png', 'sha256': 'a38288808d1461b086a283971a8e64ca86a5d2256ef44b6c21da44690b6469d8', 'base64': ''}}
STATIC_BADGES['power'] = {'url': 'https://www.blablalink.com/assets/nikke/version/default/assets/team-combat-icon-Dh5bTU7x.png', 'sha256': '28728ba3e5c0599828c5b8d83d40abe745d10f37187b010da38c1ff78f4a781c', 'base64': ''}
POWER_PRESENTATION = {
    'label': 'POWER', 'value_source': 'context.combat',
    'presentation': 'data_value_with_original_typography',
    'numeric_image_api': False,
}


def base_icon_spec(kind, key):
    if not isinstance(kind, str) or not isinstance(key, str):
        return None
    return BASE_ICON_MAP.get((kind, key))


def cache_static_badges(images, *, disk_limit=None):
    """Materialize reviewed bundled images locally; never perform HTTP."""
    from .cache import atomic_write
    for key, badge in STATIC_BADGES.items():
        path = (images.root / 'rolemeta' / 'power' / 'team_combat.png' if key == 'power'
                else images.root / 'rolemeta' / 'breakthrough' / (key + '.png'))
        data = base64.b64decode(badge['base64'], validate=True)
        digest = hashlib.sha256(data).hexdigest()
        if digest != badge['sha256']:
            raise ValueError('bundled badge digest mismatch')
        meta = {'url': badge['url'], 'sha256': digest, 'source_sha256': digest,
                'origin': 'reviewed_official_bundled_png', 'contains_value': False}
        meta_path = path.with_suffix('.json')
        from .cache import read_metadata
        previous = read_metadata(meta_path)
        if (path.is_file() and path.read_bytes() == data and previous.get('url') == badge['url']
                and previous.get('sha256') == digest):
            continue
        serialized = json.dumps(meta, ensure_ascii=False, sort_keys=True).encode()
        if disk_limit is not None:
            used = sum(p.stat().st_size for p in images.root.rglob('*') if p.is_file())
            old_size = (path.stat().st_size if path.is_file() else 0) + (meta_path.stat().st_size if meta_path.is_file() else 0)
            if used + len(data) + len(serialized) - old_size > disk_limit:
                continue
        if not path.is_file() or path.read_bytes() != data:
            atomic_write(path, data)
        if not meta_path.is_file() or meta_path.read_bytes() != serialized:
            atomic_write(meta_path, serialized)


def static_badge_source(images, key):
    from .cache import image_data_uri
    badge = STATIC_BADGES.get(key)
    if badge is None:
        return None
    return image_data_uri(base64.b64decode(badge['base64'], validate=True), (128, 128))


async def ensure_base_icon_library(resources, http=None, *, max_downloads=None,
                                   disk_limit=None, should_stop=None, report=None):
    """Fill missing/changed fixed sources, sharing the parent's public budgets.

    Hits survive restarts and TTL expiry. The finite catalogue is the resumable
    work list: unattempted and failed entries stay in missing, with cooldowns in
    image sidecars. Refusals from the database adapter deliberately escape.
    """
    from .cache import ImageCache, MAX_BYTES, read_metadata
    source = resources.images
    images = source if http is None else ImageCache(source.root, http=http, clock=source.clock)
    report = {} if report is None else report
    report.update(checked=0, available=0, downloaded=0, attempted=0,
                  missing=[], stopped=False, stop_reason='')
    used = sum(p.stat().st_size for p in images.root.rglob('*') if p.is_file()) if disk_limit is not None else 0
    for spec in BASE_ICONS:
        report['checked'] += 1
        local = images.local_base_icon(spec.kind, spec.key)
        if local is not None:
            report['available'] += 1
            continue
        path = images.root / spec.directory / (spec.key + '.png')
        meta = read_metadata(path.with_suffix('.json'))
        blocked = images.clock() < meta.get('retry_after', 0)
        if images.clock() < images.base_icon_retry_after():
            report.update(stopped=True, stop_reason='source_cooldown')
            blocked = True
        if should_stop and should_stop():
            report.update(stopped=True, stop_reason='time_budget')
            blocked = True
        if max_downloads is not None and report['attempted'] >= max(0, max_downloads):
            report.update(stopped=True, stop_reason='task_budget')
            blocked = True
        if disk_limit is not None and used + MAX_BYTES > disk_limit:
            report.update(stopped=True, stop_reason='disk_budget')
            blocked = True
        if blocked:
            report['missing'].append(f'{spec.kind}:{spec.key}')
            continue
        old_size = path.stat().st_size if path.is_file() else 0
        report['attempted'] += 1
        data = await images.get_base_icon(spec.kind, spec.key)
        if data:
            report['available'] += 1
            report['downloaded'] += 1
            used += len(data) - old_size
        else:
            report['missing'].append(f'{spec.kind}:{spec.key}')
    from .badges import local_badge, badge_path, FALLBACK_ORIGIN
    report['fallback'] = []
    for key in STATIC_BADGES:
        report['checked'] += 1
        if local_badge(images, key) is not None:
            report['available'] += 1
            continue
        path = badge_path(images, key)
        meta = read_metadata(path.with_suffix('.json'))
        blocked = images.clock() < meta.get('retry_after', 0) and meta.get('retry_url', STATIC_BADGES[key]['url']) == STATIC_BADGES[key]['url']
        if images.clock() < images.base_icon_retry_after():
            report.update(stopped=True, stop_reason='source_cooldown')
            blocked = True
        if should_stop and should_stop():
            report.update(stopped=True, stop_reason='time_budget')
            blocked = True
        if max_downloads is not None and report['attempted'] >= max(0, max_downloads):
            report.update(stopped=True, stop_reason='task_budget')
            blocked = True
        if disk_limit is not None and used + MAX_BYTES > disk_limit:
            report.update(stopped=True, stop_reason='disk_budget')
            blocked = True
        if blocked:
            report['missing'].append('badges:' + key)
            continue
        old_size = path.stat().st_size if path.is_file() else 0
        report['attempted'] += 1
        data = await images.get_badge(key)
        if data:
            report['available'] += 1
            used += len(data) - old_size
            if read_metadata(path.with_suffix('.json')).get('origin') == FALLBACK_ORIGIN:
                report['fallback'].append(key)
                report['missing'].append('badges:' + key)
            else:
                report['downloaded'] += 1
        else:
            report['missing'].append('badges:' + key)
    report['pending'] = len(report['missing'])
    return report
